steps.bash:
set -euo pipefail
# The candidate under test is the registry's latest create-lamaste (the
# campaign publishes it to the dev Feria); the release it upgrades from is
# the highest version below it, installed exactly as a relay has it.
LATEST="$(npm view @lamalibre/create-lamaste dist-tags.latest)"
PREVIOUS="$(npm view @lamalibre/create-lamaste versions --json | LATEST="${LATEST}" node -e '
const versions = JSON.parse(require("fs").readFileSync(0, "utf8"));
const key = (v) => v.split(".").map(Number);
const below = (a, b) => { const x = key(a), y = key(b); for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] < y[i]; return false; };
const older = [].concat(versions).filter((v) => /^\d+\.\d+\.\d+$/.test(v) && below(v, process.env.LATEST));
older.sort((a, b) => (below(a, b) ? -1 : 1));
if (older.length === 0) process.exit(1);
process.stdout.write(older[older.length - 1]);
')"
echo "candidate ${LATEST}, installing ${PREVIOUS}"
npm install -g "@lamalibre/create-lamaste@${PREVIOUS}"
create-lamaste --dev --skip-harden --yes
